  c.field("base", [](const Value& self) -> Value { return call(K(S<"Sweep">()), S<"base_env">(), { get(self, S<"model">()) }); });
  c.field("order", [](const Value& self) -> Value { return list({ "mass", "face", "moving", "radiating" }); });
  c.field("axes", [](const Value& self) -> Value { return get(K(S<"Sweep">()), S<"axes_of">()); });
  c.field("R0", [](const Value& self) -> Value { return neg(1.0); });
